                            onNavigateToOrders: () => onNavigate(_ordersTab),
                            onNavigateToTarget: onNavigateToTarget,
                          ),
                        ),
                    ],
                  ),
                ),

              // 5 · Today so far divider
              _RSection(
                top: PosSpacing.sp6,
                child: Column(
                  children: [
                    _DividerBand(
                      en: 'Today so far · ${money?.kpis.orders ?? 0} orders',
