class _TerminalFloorPreview extends StatelessWidget {
  const _TerminalFloorPreview({required this.busy, required this.total});

  final int busy;
  final int total;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _SecHead(
          en: 'Floor',
          bn: 'ফ্লোর',
          action: '$busy of $total busy',
          actionBn: '$busy/$total ব্যস্ত',
        ),
        const SizedBox(height: PosSpacing.sp3),
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: PosColors.surface,
            borderRadius: BorderRadius.circular(PosRadii.md),
            border: Border.all(color: PosColors.line, width: 0.5),
          ),
          child: Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(total, (i) {
              final isBusy = i < busy;
              return Container(
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  color: isBusy ? PosColors.primarySoft : PosColors.surfaceSunk,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: isBusy ? PosColors.primary : PosColors.line,
                    width: 0.5,
                  ),
                ),
                alignment: Alignment.center,
                child: Text(
                  'T${i + 1}',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: isBusy ? PosColors.primaryDark : PosColors.muted,
                  ),
                ),
              );
            }),
          ),
        ),
      ],
    );
  }
}

