class _DashT2Standard extends StatelessWidget {
  const _DashT2Standard({
    required this.app,
    required this.onNavigate,
    this.onNavigateToTarget,
    required this.mode,
    required this.onModeChanged,
  });

  final dynamic app;
  final ValueChanged<int> onNavigate;
  final ValueChanged<PosNotificationTarget>? onNavigateToTarget;
  final _DashMode mode;
  final ValueChanged<_DashMode> onModeChanged;

  @override
  Widget build(BuildContext context) {
    final text = app.strings as AppStrings;
    final summary = app.dashboardSummary as DashboardSummary?;
    final money = summary?.moneyFirst;
    final right = summary?.rightNow;

    final earned = money?.earnedToday ?? 0.0;
    final moneyFmt = NumberFormat('#,##0', 'en');
    final earnedStr = '৳${moneyFmt.format(earned)}';

    final openOrders = (app.orders as List<OrderModel>)
        .where((o) => o.status.adminStatus.isOpen)
        .toList(growable: false);
    final openTotal = openOrders.fold<double>(0, (sum, o) => sum + o.total);
    final lateCount = openOrders
        .where((o) => o.status.adminStatus == OrderStatus.pending)
        .length;

    final alerts = right?.needsAttention ?? [];
    final menuItems = (app.menuItems as List<MenuItem>)
        .where((item) => item.isAvailable)
        .take(9)
        .toList(growable: false);

    return Scaffold(
      backgroundColor: PosColors.background,
      body: SafeArea(
        child: RefreshIndicator(
          color: PosColors.primaryDark,
          backgroundColor: PosColors.primary,
          onRefresh: () => app.refreshDashboardSummary(),
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.only(bottom: 100),
            children: [
              _DashHeader(
                bizName: app.serverConfig?.restaurantName ?? 'My Cafe',
                onNavigateToOrders: () => onNavigate(_ordersTab),
                onNavigateToTarget: onNavigateToTarget,
                mode: mode,
                onModeChanged: onModeChanged,
                drawerAmount: earnedStr,
              ),

              // 1 · Right Now strip
              _RSection(
                top: 4,
                child: _OpenTicketsStrip(
                  count: openOrders.length,
                  total: '৳${moneyFmt.format(openTotal)}',
                  late: lateCount,
                  onTap: () => onNavigate(_ordersTab),
                ),
              ),

              // 2 · Ring it up (Search + Grid)
              _RSection(
                top: PosSpacing.sp5,
                child: const _RingupSearch(),
              ),

              _RSection(
                top: PosSpacing.sp4,
                child: _TerminalFohCounter(
                  items: menuItems,
                  onTap: (item) => unawaited(
                    openNewOrderForm(context, onCreated: () => onNavigate(0)),
                  ),
                ),
              ),

              // 3 · Floor map preview
              _RSection(
                top: PosSpacing.sp5,
                child: _TerminalFloorPreview(
                  busy: openOrders.length,
                  total: 6,
                ),
              ),

              // 4 · Needs attention
              if (alerts.isNotEmpty)
                _RSection(
                  top: PosSpacing.sp5,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      _SecHead(
                        en: 'Needs attention',
                        bn: 'মনোযোগ প্রয়োজন',
                        count: alerts.length,
                      ),
                      const SizedBox(height: PosSpacing.sp3),
                      for (final a in alerts)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 8),
                          child: _AttentionCard(
                            item: a,
                            onNavigateToOrders: () => onNavigate(_ordersTab),
                            onNavigateToTarget: onNavigateToTarget,
                          ),
                        ),
                    ],
                  ),
                ),

              // 5 · Today so far divider
              _RSection(
                top: PosSpacing.sp6,
                child: Column(
                  children: [
                    _DividerBand(
                      en: 'Today so far · ${money?.kpis.orders ?? 0} orders',
                      bn: 'আজকের হিসাব · ${money?.kpis.orders ?? 0} অর্ডার',
                    ),
                    const SizedBox(height: PosSpacing.sp3),
                    Text(
                      earnedStr,
                      style: const TextStyle(
                        fontSize: 24,
                        fontWeight: FontWeight.w700,
                        color: PosColors.primaryDark,
                        letterSpacing: -0.5,
                      ),
                    ),
                  ],
                ),
              ),

              // 6 · End of day
              _RSection(
                top: PosSpacing.sp5,
                child: _TerminalCloseCard(
                  title: text.isBn ? 'দিন শেষ করুন' : 'Close day',
                  amount: earnedStr,
                  warn: openOrders.isEmpty
                      ? null
                      : tfPick(context,
                          en: '${openOrders.length} open orders remaining',
                          bn: '${openOrders.length}টি খোলা অর্ডার বাকি আছে'),
                  onOpenSettings: () => onNavigate(3),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _TerminalFloorPreview extends StatelessWidget {
  const _TerminalFloorPreview({required this.busy, required this.total});

  final int busy;
  final int total;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _SecHead(
          en: 'Floor',
          bn: 'ফ্লোর',
          action: '$busy of $total busy',
          actionBn: '$busy/$total ব্যস্ত',
        ),
        const SizedBox(height: PosSpacing.sp3),
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: PosColors.surface,
            borderRadius: BorderRadius.circular(PosRadii.md),
            border: Border.all(color: PosColors.line, width: 0.5),
          ),
          child: Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(total, (i) {
              final isBusy = i < busy;
              return Container(
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  color: isBusy ? PosColors.primarySoft : PosColors.surfaceSunk,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: isBusy ? PosColors.primary : PosColors.line,
                    width: 0.5,
                  ),
                ),
                alignment: Alignment.center,
                child: Text(
                  'T${i + 1}',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: isBusy ? PosColors.primaryDark : PosColors.muted,
                  ),
                ),
              );
            }),
          ),
        ),
      ],
    );
  }
}

