// ── Review · Standard (Simple + Standard tiers) ──────────────────────────────
class _ReviewStandard extends StatelessWidget {
  const _ReviewStandard({
    required this.app,
    required this.onNavigate,
    this.onNavigateToTarget,
    required this.mode,
    required this.onModeChanged,
  });

  final dynamic app;
  final ValueChanged<int> onNavigate;
  final ValueChanged<PosNotificationTarget>? onNavigateToTarget;
  final _DashMode mode;
  final ValueChanged<_DashMode> onModeChanged;

  @override
  Widget build(BuildContext context) {
    final review = (app.dashboardSummary as DashboardSummary?)?.review;
    final sections = <Widget>[];

    if (review == null) {
      sections.add(
        const _RSection(
          top: 0,
          fullBleed: true,
          child: _ReviewEmptyNote(
            'Review data will appear once today\'s sales sync.',
            bn: 'আজকের বিক্রি সিঙ্ক হলে পর্যালোচনার তথ্য দেখা যাবে।',
          ),
        ),
      );
    } else {
      final hero = review.hero;
      final diff = hero.earnedTodayBdt - hero.earnedYesterdayBdt;
      sections.addAll([
        _RSection(
          top: 0,
          fullBleed: true,
          child: _ReviewHero(
            amount: _bdt(hero.earnedTodayBdt),
            label: 'Earned today',
            bn: 'আজকের আয়',
            deltaText: '${diff >= 0 ? '+' : '-'}${_bdt(diff.abs())}',
            deltaUp: hero.deltaUp,
            baseLabel: tfPick(
              context,
              en: 'vs yesterday',
              bn: 'গতকালকের তুলনায়',
            ),
            note: hero.periodNote,
          ),
        ),
        _RSection(
          top: PosSpacing.sp4,
          child: LayoutBuilder(
            builder: (context, constraints) {
              return Row(
                children: [
                  Expanded(
                    child: _KpiTile(
                      labelEn: 'Orders',
                      labelBn: 'অর্ডার',
                      value: '${review.kpis.orders}',
                    ),
                  ),
                  const SizedBox(width: PosSpacing.sp3),
                  Expanded(
                    child: _KpiTile(
                      labelEn: 'Covers',
                      labelBn: 'অতিথি',
                      value: '${review.kpis.covers}',
                    ),
                  ),
                  if (review.kpis.foodCostPct != null) ...[
                    const SizedBox(width: PosSpacing.sp3),
                    Expanded(
                      child: _KpiTile(
                        labelEn: 'Profit',
                        labelBn: 'লাভ',
                        value: '${100 - (review.kpis.foodCostPct ?? 0).round()}%',
                        tone: _TileTone.accent,
                      ),
                    ),
                  ],
                ],
              );
            },
          ),
        ),
        _RSection(
          top: PosSpacing.sp5,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const _SecHead(en: 'Hot selling today', bn: 'আজকের টপ আইটেম'),
              const SizedBox(height: PosSpacing.sp3),
              review.itemsSold.isEmpty
                  ? const _ReviewEmptyNote(
                      'No sales recorded yet today.',
                      bn: 'আজ এখনো কোনো বিক্রি রেকর্ড হয়নি।',
                    )
                  : _RowsCard(
                      children: [
                        for (int i = 0; i < review.itemsSold.length; i++)
                          _ReviewItemRow(
                            rank: i + 1,
                            item: review.itemsSold[i],
                          ),
                      ],
                    ),
            ],
          ),
        ),
        if (review.issues.isNotEmpty)
          _RSection(
            top: PosSpacing.sp5,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _SecHead(
                  en: "Operational issues",
                  bn: 'অপারেশনাল সমস্যা',
                  count: review.issues.length,
                ),
                const SizedBox(height: PosSpacing.sp3),
                _RowsCard(
                  children: [
                    for (final issue in review.issues) _IssueRow(issue),
                  ],
                ),
              ],
            ),
          ),
        _RSection(
          top: PosSpacing.sp5,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const _SecHead(en: 'Sales by source', bn: 'সোর্স অনুযায়ী বিক্রি'),
              const SizedBox(height: PosSpacing.sp3),
              _CollapsedSourceCard(rows: review.bySource),
            ],
          ),
        ),
      ]);
    }

    return _reviewScaffold(
      app: app,
      period: tfPick(context, en: 'Today', bn: 'আজ'),
      mode: mode,
      onModeChanged: onModeChanged,
      onNavigate: onNavigate,
      onNavigateToTarget: onNavigateToTarget,
      sections: sections,
    );
  }
