import 'dart:async';

import 'package:flutter/material.dart';
import 'package:intl/intl.dart';

import '../../app_scope.dart';
import '../../core/enums/business_tier.dart';
import '../../core/localization/app_strings.dart';
import '../../core/theme/app_theme.dart';
import '../../core/widgets/hourly_bars_chart.dart';
import '../../core/widgets/menu_image_view.dart';
import '../../core/widgets/notification_center.dart';
import '../../core/widgets/tf_design_system.dart';
import '../../models/dashboard_summary.dart';
import '../../models/menu_item.dart';
import '../../models/order_service_type.dart';
import '../../models/pos_notification.dart';
import '../desktop_pos/widgets/menu_line_customizer.dart';
import '../orders/orders_screen.dart';

// Tab indices mirroring _AppTab in app.dart.
const int _ordersTab = 0;
const int _stockTab = 3;
const int _settingsTab = 4;

class DashboardScreen extends StatefulWidget {
  const DashboardScreen({
    required this.onNavigate,
    this.onNavigateToTarget,
    super.key,
  });

  final ValueChanged<int> onNavigate;
  final ValueChanged<PosNotificationTarget>? onNavigateToTarget;

  @override
  State<DashboardScreen> createState() => _DashboardScreenState();
}

class _DashboardScreenState extends State<DashboardScreen> {
  bool _firstLoadKicked = false;
  _DashMode _mode = _DashMode.manage;

  void _setMode(_DashMode mode) {
    if (_mode == mode) return;
    setState(() => _mode = mode);
  }

  @override
  Widget build(BuildContext context) {
    final app = AppScope.of(context);
    final tier = app.businessTier;

    if (!_firstLoadKicked) {
      _firstLoadKicked = true;
      WidgetsBinding.instance.addPostFrameCallback(
        (_) => app.refreshDashboardSummary(),
      );
    }

    final mode = app.isManager ? _mode : _DashMode.manage;
    if (mode == _DashMode.review) {
      // Review has three variants; Simple falls back to the Standard screen.
      return switch (tier) {
        BusinessTier.simple || BusinessTier.standard => _ReviewStandard(
          app: app,
          onNavigate: widget.onNavigate,
          onNavigateToTarget: widget.onNavigateToTarget,
          mode: mode,
          onModeChanged: _setMode,
        ),
        BusinessTier.advanced => _ReviewAdvanced(
          app: app,
          onNavigate: widget.onNavigate,
          onNavigateToTarget: widget.onNavigateToTarget,
          mode: mode,
          onModeChanged: _setMode,
        ),
        BusinessTier.enterprise => _ReviewEnterprise(
          app: app,
          onNavigate: widget.onNavigate,
          onNavigateToTarget: widget.onNavigateToTarget,
          mode: mode,
          onModeChanged: _setMode,
        ),
      };
    }

    return switch (tier) {
      BusinessTier.simple => _DashT1Counter(
        app: app,
        onNavigate: widget.onNavigate,
        onNavigateToTarget: widget.onNavigateToTarget,
        mode: mode,
        onModeChanged: _setMode,
      ),
      BusinessTier.standard => _DashT2Standard(
        app: app,
        onNavigate: widget.onNavigate,
        onNavigateToTarget: widget.onNavigateToTarget,
        mode: mode,
        onModeChanged: _setMode,
      ),
      BusinessTier.advanced => _DashT3Full(
        app: app,
        onNavigate: widget.onNavigate,
        onNavigateToTarget: widget.onNavigateToTarget,
        mode: mode,
        onModeChanged: _setMode,
      ),
      BusinessTier.enterprise => _DashT4Fleet(
        app: app,
        onNavigate: widget.onNavigate,
        onNavigateToTarget: widget.onNavigateToTarget,
        mode: mode,
        onModeChanged: _setMode,
      ),
    };
  }
}

// ── Shared helpers ───────────────────────────────────────────────────────────

// Uppercase micro-label in tabular mono spacing.
class _MicroLabel extends StatelessWidget {
  const _MicroLabel(this.text);
  final String text;

  @override
  Widget build(BuildContext context) => Text(
        text.toUpperCase(),
        style: TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w600,
          color: PosColors.mutedSoft,
          letterSpacing: 11 * 0.07,
          fontFeatures: const [FontFeature.tabularFigures()],
        ),
      );
}

// Dashboard app-bar with greeting, biz name, mode dropdown, and bells.
class _DashHeader extends StatelessWidget {
  const _DashHeader({
    required this.bizName,
    required this.onNavigateToOrders,
    required this.onNavigateToTarget,
    required this.mode,
    required this.onModeChanged,
    this.period,
    this.drawerAmount,
  });

  final String bizName;
  final VoidCallback onNavigateToOrders;
  final ValueChanged<PosNotificationTarget>? onNavigateToTarget;
  final _DashMode mode;
  final ValueChanged<_DashMode> onModeChanged;

  /// Optional period chip shown on the right of the Manage/Review switcher
  /// (e.g. "Today", "Today · Fleet"). Used by the Review screens.
  final String? period;

  /// Optional cash drawer amount shown in the Manage Mode header.
  final String? drawerAmount;

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final hour = now.hour;
    final text = AppScope.of(context).strings;
    final greet = hour < 12
        ? text.goodMorning
        : (hour < 17 ? text.goodAfternoon : text.goodEvening);
    final dateFmt = DateFormat('EEE d MMM · h:mm a');

    final isManage = mode == _DashMode.manage;

    final identity = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (isManage) ...[
          TfText(
            bizName,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.w700,
              color: PosColors.primaryDark,
              height: 1.1,
              letterSpacing: -0.4,
            ),
          ),
          const SizedBox(height: 6),
          Wrap(
            spacing: 6,
            runSpacing: 4,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              _MiniTag(
                switch (AppScope.of(context).businessTier) {
                  BusinessTier.simple => 'FOOD CART',
                  BusinessTier.standard => 'CAFE',
                  BusinessTier.advanced => 'RESTAURANT',
                  BusinessTier.enterprise => 'FLEET',
                },
              ),
              Text(
                DateFormat('h:mm a · EEE d MMM').format(now),
                style: const TextStyle(
                  fontSize: 11.5,
                  color: PosColors.muted,
                  fontWeight: FontWeight.w600,
                ),
              ),
              if (drawerAmount != null)
                Text(
                  drawerAmount!,
                  style: const TextStyle(
                    fontSize: 11.5,
                    color: PosColors.primaryDark,
                    fontWeight: FontWeight.w700,
                  ),
                ),
            ],
          ),
        ] else ...[
          _MicroLabel(DateFormat('EEE · h:mm a').format(now)),
          const SizedBox(height: 4),
          Text(
            bizName,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              fontSize: 17,
              fontWeight: FontWeight.w600,
              color: PosColors.primaryDark,
              letterSpacing: -0.3,
              height: 1.15,
            ),
          ),
          const SizedBox(height: 3),
          Text(
            greet,
            style: const TextStyle(fontSize: 12, color: PosColors.muted),
          ),
        ],
      ],
    );

    final actions = <Widget>[
      if (AppScope.of(context).isManager)
        _ReviewTabs(mode: mode, onChanged: onModeChanged),
      HeaderNotificationBell(
        onNavigateToOrders: onNavigateToOrders,
        onNavigateToTarget: onNavigateToTarget,
      ),
    ];

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(child: identity),
              const SizedBox(width: 8),
              _HeaderActionBar(actions: actions),
            ],
          ),
          if (period != null) ...[
            const SizedBox(height: 12),
            Align(
              alignment: Alignment.centerRight,
              child: _PeriodChip(period: period!),
            ),
          ],
        ],
      ),
    );
  }
}

class _MiniTag extends StatelessWidget {
  const _MiniTag(this.label);

  final String label;

  @override
  Widget build(BuildContext context) => Container(
        padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
        decoration: BoxDecoration(
          color: PosColors.surfaceSunk,
          borderRadius: BorderRadius.circular(PosRadii.xs),
          border: Border.all(color: PosColors.line, width: 0.5),
        ),
        child: Text(
          label,
          style: const TextStyle(
            fontSize: 9.5,
            fontWeight: FontWeight.w700,
            color: PosColors.muted,
            letterSpacing: 0.6,
          ),
        ),
      );
}

class _OpenTicketsStrip extends StatelessWidget {
  const _OpenTicketsStrip({
    required this.count,
    required this.total,
    required this.late,
    this.onTap,
  });

  final int count;
  final String total;
  final int late;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) => GestureDetector(
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          decoration: BoxDecoration(
            color: PosColors.surface,
            borderRadius: BorderRadius.circular(PosRadii.md),
            boxShadow: PosShadows.soft,
          ),
          child: Row(
            children: [
              const Icon(
                Icons.receipt_long_outlined,
                size: 18,
                color: PosColors.muted,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  '$count open tickets',
                  style: const TextStyle(
                    fontSize: 12.5,
                    fontWeight: FontWeight.w700,
                    color: PosColors.primaryDark,
                  ),
                ),
              ),
              Text(
                total,
                style: const TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w700,
                  color: PosColors.primaryDark,
                ),
              ),
              if (late > 0) ...[
                const SizedBox(width: 8),
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                  decoration: BoxDecoration(
                    color: PosColors.urgentSoft,
                    borderRadius: BorderRadius.circular(PosRadii.xs),
                  ),
                  child: Text(
                    '$late late',
                    style: const TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                      color: PosColors.urgent,
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      );
}

class _RingupSearch extends StatelessWidget {
  const _RingupSearch({this.onTap});
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) => GestureDetector(
        onTap: onTap,
        child: Container(
          height: 44,
          padding: const EdgeInsets.symmetric(horizontal: 12),
          decoration: BoxDecoration(
            color: PosColors.surfaceSunk,
            borderRadius: BorderRadius.circular(PosRadii.sm),
            border: Border.all(color: PosColors.line, width: 0.5),
          ),
          child: Row(
            children: [
              const Icon(Icons.search_rounded, size: 18, color: PosColors.muted),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  tfPick(context,
                      en: 'Search item or scan code',
                      bn: 'আইটেম খুঁজুন বা কোড স্ক্যান করুন'),
                  style: const TextStyle(
                    fontSize: 13,
                    color: PosColors.muted,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ],
          ),
        ),
      );
}

class _TerminalFohCounter extends StatelessWidget {
  const _TerminalFohCounter({required this.items, required this.onTap});

  final List<MenuItem> items;
  final ValueChanged<MenuItem> onTap;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _SecHead(
          en: 'Top sellers · tap to add',
          bn: 'বেশি বিক্রি · যোগ করতে ট্যাপ করুন',
          action: 'Edit',
          actionBn: 'এডিট',
        ),
        const SizedBox(height: PosSpacing.sp3),
        if (items.isEmpty)
          TfCard(
            padding: const EdgeInsets.all(18),
            child: const Text(
              'No menu items yet',
              style: TextStyle(color: PosColors.muted, fontSize: 13),
            ),
          )
        else
          GridView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 3,
              crossAxisSpacing: 8,
              mainAxisSpacing: 8,
              childAspectRatio: 0.98,
            ),
            itemCount: items.length,
            itemBuilder: (context, index) => _TerminalFohTile(
              item: items[index],
              onTap: () => onTap(items[index]),
            ),
          ),
      ],
    );
  }
}

class _TerminalFohTile extends StatelessWidget {
  const _TerminalFohTile({required this.item, required this.onTap});

  final MenuItem item;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) => Material(
        color: PosColors.surface,
        borderRadius: BorderRadius.circular(12),
        child: InkWell(
