  });

  final dynamic app;
  final ValueChanged<int> onNavigate;
  final ValueChanged<PosNotificationTarget>? onNavigateToTarget;
  final _DashMode mode;
  final ValueChanged<_DashMode> onModeChanged;

  @override
  Widget build(BuildContext context) {
    final text = app.strings as AppStrings;
    final summary = app.dashboardSummary as DashboardSummary?;
    final money = summary?.moneyFirst;
    final right = summary?.rightNow;

    final earned = money?.earnedToday ?? 0.0;
    final moneyFmt = NumberFormat('#,##0', 'en');
    final earnedStr = '৳${moneyFmt.format(earned)}';

    final openOrders = (app.orders as List<OrderModel>)
        .where((o) => o.status.adminStatus.isOpen)
        .toList(growable: false);
    final openTotal = openOrders.fold<double>(0, (sum, o) => sum + o.total);
    final lateCount = openOrders
        .where((o) => o.status.adminStatus == OrderStatus.pending)
        .length;

    final alerts = right?.needsAttention ?? [];
    final menuItems = (app.menuItems as List<MenuItem>)
        .where((item) => item.isAvailable)
        .take(9)
        .toList(growable: false);

    return Scaffold(
      backgroundColor: PosColors.background,
      body: SafeArea(
        child: RefreshIndicator(
          color: PosColors.primaryDark,
          backgroundColor: PosColors.primary,
          onRefresh: () => app.refreshDashboardSummary(),
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.only(bottom: 100),
            children: [
              _DashHeader(
                bizName: app.serverConfig?.restaurantName ?? 'My Restaurant',
                onNavigateToOrders: () => onNavigate(_ordersTab),
                onNavigateToTarget: onNavigateToTarget,
                mode: mode,
                onModeChanged: onModeChanged,
                drawerAmount: earnedStr,
              ),

              // 1 · Right Now strip
              _RSection(
                top: 4,
                child: _OpenTicketsStrip(
                  count: openOrders.length,
                  total: '৳${moneyFmt.format(openTotal)}',
                  late: lateCount,
                  onTap: () => onNavigate(_ordersTab),
                ),
              ),

              // 2 · Tower KPIs
              _RSection(
                top: PosSpacing.sp5,
                child: Row(
                  children: [
                    Expanded(
                      child: _TowerTile(
                        value: moneyFmt.format(earned),
                        sub: 'Sales',
                        bn: 'বিক্রি',
                        tone: _TileTone.paper,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: _TowerTile(
                        value: '${right?.tablesSeated ?? 0}',
                        sub: 'Guests',
                        bn: 'অতিথি',
                        tone: _TileTone.accent,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: _TowerTile(
                        value: '4.8',
                        valueSuffix: '★',
                        sub: 'Staff',
                        bn: 'স্টাফ',
                        tone: _TileTone.paper,
                      ),
                    ),
                  ],
                ),
              ),

              // 3 · Ring it up (Search + Grid)
              _RSection(
                top: PosSpacing.sp5,
                child: const _RingupSearch(),
              ),

              _RSection(
                top: PosSpacing.sp4,
                child: _TerminalFohCounter(
                  items: menuItems,
                  onTap: (item) => unawaited(
                    openNewOrderForm(context, onCreated: () => onNavigate(0)),
                  ),
                ),
              ),

              // 4 · Floor map preview (Expanded)
              _RSection(
                top: PosSpacing.sp5,
                child: _TerminalFloorPreview(
                  busy: openOrders.length,
                  total: 12,
                ),
              ),

              // 5 · Needs attention
              if (alerts.isNotEmpty)
                _RSection(
                  top: PosSpacing.sp5,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      _SecHead(
                        en: 'Needs attention',
                        bn: 'মনোযোগ প্রয়োজন',
                        count: alerts.length,
                      ),
                      const SizedBox(height: PosSpacing.sp3),
                      for (final a in alerts)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 8),
                          child: _AttentionCard(
                            item: a,
                            onNavigateToOrders: () => onNavigate(_ordersTab),
                            onNavigateToTarget: onNavigateToTarget,
                          ),
                        ),
                    ],
                  ),
                ),

              // 6 · End of shift
              _RSection(
                top: PosSpacing.sp5,
                child: _TerminalCloseCard(
                  title: text.isBn ? 'শিফট শেষ করুন' : 'End shift',
                  amount: earnedStr,
                  warn: openOrders.isEmpty
                      ? null
                      : tfPick(context,
                          en: '${openOrders.length} open orders carry over',
                          bn: '${openOrders.length}টি খোলা অর্ডার পরের শিফটে যাবে'),
                  onOpenSettings: () => onNavigate(3),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _TerminalFloorPreview extends StatelessWidget {
