              context,
              en: 'vs yesterday',
              bn: 'গতকালকের তুলনায়',
            ),
            note: hero.periodNote,
          ),
        ),
        _RSection(
          top: PosSpacing.sp4,
          child: LayoutBuilder(
            builder: (context, constraints) {
              return Row(
                children: [
                  Expanded(
                    child: _KpiTile(
                      labelEn: 'Orders',
